// Initialise loop state. Replace the payload with whatever Trigger emits.
return [{
  json: {
    payload: $input.first()?.json ?? {},
    attempt: 0,
    maxAttempts: 3,
    backoffMs: [2000, 4000, 8000],
    correlationId: `tpl-retry-${Date.now()}-${Math.floor(Math.random() * 1e6)}`
  }
}];

// $input here is the HTTP result, not the loop state, so read the state from
// 'Init loop state' (it runs once) and count attempts with $runIndex
// (how many times this node has run in this execution).
const s = $('Init loop state').first().json;
const nextAttempt = $runIndex + 1;
if (nextAttempt > s.maxAttempts) {
  return [{ json: { ...s, attempt: nextAttempt, exhausted: true } }];
}
return [{ json: { ...s, attempt: nextAttempt, exhausted: false, waitMs: s.backoffMs[nextAttempt - 1] } }];

// Replace this Code node with your real dead-letter sink (Slack / email / queue).
const current = $input.first().json;
return [{
  json: {
    deadLetter: true,
    reason: 'max retries exhausted',
    correlationId: current.correlationId,
    finalAttempt: current.attempt,
    snapshot: current.payload
  }
}];
